import{_ as l,a0 as n,w as a,s as p,ao as m,I as i,x as t,a1 as s,A as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"如何设置 Linux 上 SSH 登录的 Email 提醒 | LCTT x X-CMD","titleTemplate":false,"description":"如何设置 Linux 上 SSH 登录的 Email 提醒 | LCTT (201504) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何设置 Linux 上 SSH 登录的 Email 提醒 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何设置 Linux 上 SSH 登录的 Email 提醒 | LCTT (201504) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201504/20150310 How To Get Email Alerts for SSH Login on Linux Server","title":"如何设置 Linux 上 SSH 登录的 Email 提醒","tag":"201504","desc":""},"relativePath":"201504/20150310 How To Get Email Alerts for SSH Login on Linux Server.md","filePath":"[post].md"}'),u={name:"201504/20150310 How To Get Email Alerts for SSH Login on Linux Server.md"};function f(c,o,d,S,h,w){const e=n("Link");return a(),p("div",null,[o[13]||(o[13]=m('<h1 id="如何设置-linux-上-ssh-登录的-email-提醒" tabindex="-1">如何设置 Linux 上 SSH 登录的 Email 提醒 <a class="header-anchor" href="#如何设置-linux-上-ssh-登录的-email-提醒" aria-label="Permalink to “如何设置 Linux 上 SSH 登录的 Email 提醒”">​</a></h1><p><img src="http://www.ehowstuff.com/wp-content/uploads/2015/03/fail2ban-security.jpg" alt=""></p><p>虚拟私有服务器 （VPS）上启用 SSH 服务使得该服务器暴露到互联网中，为黑客攻击提供了机会，尤其是当 VPS 还允许root 直接访问时。VPS 应该为每次 SSH 登录成功尝试配置一个自动的 email 警告。 VPS 服务器的所有者会得到各种 SSH 服务器访问日志的通知，例如登录者、登录时间以及来源 IP 地址等信息。这是一个对于服务器拥有者来说，保护服务器避免未知登录尝试的重要安全关注点。这是因为如果黑客使用暴力破解方式通过 SSH 来登录到你的 VPS 的话，后果很严重。在本文中，我会解释如何在 CentOS 6、 CentOS 7、 RHEL 6 和 RHEL 7上为所有的 SSH 用户登录设置一个 email 警告。</p><ol><li><p>使用root用户登录到你的服务器；</p></li><li><p>在全局源定义处配置警告（/etc/bashrc），这样就会对 root 用户以及普通用户都生效：</p><pre><code> [root@vps ~]# vi /etc/bashrc\n</code></pre><p>将下面的内容加入到上述文件的尾部。</p><pre><code> echo &#39;ALERT - Root Shell Access (vps.ehowstuff.com) on:&#39; `date` `who` | mail -s &quot;Alert: Root Access from `who | cut -d&#39;(&#39; -f2 | cut -d&#39;)&#39; -f1`&quot; recipient@gmail.com\n</code></pre></li><li><p>你也可以选择性地让警告只对 root 用户生效：</p><pre><code> [root@vps ~]# vi .bashrc\n</code></pre><p>将下面的内容添加到/root/.bashrc的尾部：</p><pre><code> echo &#39;ALERT - Root Shell Access (vps.ehowstuff.com) on:&#39; `date` `who` | mail -s &quot;Alert: Root Access from `who | cut -d&#39;(&#39; -f2 | cut -d&#39;)&#39; -f1`&quot; recipient@gmail.com\n</code></pre><p>整个配置文件样例：</p><pre><code> # .bashrc\n\n # User specific aliases and functions\n\n alias rm=&#39;rm -i&#39;\n alias cp=&#39;cp -i&#39;\n alias mv=&#39;mv -i&#39;\n\n # Source global definitions\n if [ -f /etc/bashrc ]; then\n     	. /etc/bashrc\n fi\n echo &#39;ALERT - Root Shell Access (vps.ehowstuff.com) on:&#39; `date` `who` | mail -s &quot;Alert: Root Access from `who | cut -d&#39;(&#39; -f2 | cut -d&#39;)&#39; -f1`&quot; recipient@gmail.com\n</code></pre></li><li><p>你也可以选择性地让警告只对特定的普通用户生效（例如 skytech）：</p><pre><code> [root@vps ~]# vi /home/skytech/.bashrc\n</code></pre><p>将下面的内容加入到/home/skytech/.bashrc文件尾部：</p><pre><code> echo &#39;ALERT - Root Shell Access (vps.ehowstuff.com) on:&#39; `date` `who` | mail -s &quot;Alert: Root Access from `who | cut -d&#39;(&#39; -f2 | cut -d&#39;)&#39; -f1`&quot; recipient@gmail.com\n</code></pre></li></ol><hr>',5)),i("p",null,[o[1]||(o[1]=t("via: ",-1)),s(e,{href:"http://www.ehowstuff.com/how-to-get-email-alerts-for-ssh-login-on-linux-server/"},{default:r(()=>[...o[0]||(o[0]=[t("http://www.ehowstuff.com/how-to-get-email-alerts-for-ssh-login-on-linux-server/",-1)])]),_:1})]),i("p",null,[o[5]||(o[5]=t("作者：",-1)),s(e,{href:"http://www.ehowstuff.com/author/mhstar/"},{default:r(()=>[...o[2]||(o[2]=[t("skytech",-1)])]),_:1}),o[6]||(o[6]=t(" 译者：",-1)),s(e,{href:"https://github.com/theo-l"},{default:r(()=>[...o[3]||(o[3]=[t("theo-l",-1)])]),_:1}),o[7]||(o[7]=t(" 校对：",-1)),s(e,{href:"https://github.com/wxy"},{default:r(()=>[...o[4]||(o[4]=[t("wxy",-1)])]),_:1})]),i("p",null,[o[10]||(o[10]=t("本文由 ",-1)),s(e,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...o[8]||(o[8]=[t("LCTT",-1)])]),_:1}),o[11]||(o[11]=t(" 原创翻译，",-1)),s(e,{href:"http://linux.cn/"},{default:r(()=>[...o[9]||(o[9]=[t("Linux中国",-1)])]),_:1}),o[12]||(o[12]=t(" 荣誉推出",-1))])])}const A=l(u,[["render",f]]);export{x as __pageData,A as default};
